  if (roundUp) {
    let arr = kept.split('');
    let i = arr.length - 1;
    while (i >= 0) {
      if (arr[i] === '9') { arr[i] = '0'; i--; }
      else { arr[i] = String.fromCharCode(arr[i].charCodeAt(0) + 1); break; }
    }
    if (i < 0) arr.unshift('1');
    kept = arr.join('');
