  let intOut = kept.slice(0, kept.length - 2) || '0';
  let fracOut = kept.slice(kept.length - 2);
  let result = intOut + '.' + fracOut;
  if (neg && !(intOut === '0' && fracOut === '00')) result = '-' + result;
  return result;
