function solve(input) {
  let s = String(input).trim();
  let neg = false;
  if (s[0] === '+' || s[0] === '-') {
    neg = s[0] === '-';
    s = s.slice(1);
  }
  let dot = s.indexOf('.');
  let intPart, fracPart;
  if (dot === -1) {
    intPart = s;
    fracPart = '';
  } else {
    intPart = s.slice(0, dot);
    fracPart = s.slice(dot + 1);
  }
  if (intPart === '' ) intPart = '0';
  fracPart = fracPart.replace(/[^0-9]/g, ''); // safety
  let kept = (fracPart + '00').slice(0, 2);
  let rest = fracPart.slice(2);
  let roundUp = false;
  if (rest.length > 0 && /[1-9]/.test(rest)) {
    if (rest[0] > '5') roundUp = true;
    else if (rest[0] === '5') {
      // check if exactly half or more
      let tail = rest.slice(1);
      if (/[1-9]/.test(tail)) roundUp = true;
      else {
        // exactly half: round to even
        roundUp = (Number(kept[1]) % 2) === 1;
      }
    }
  }
  let num = BigInt(intPart + kept);
  if (roundUp) num += 1n;
  let str = num.toString().padStart(3, '0');
  let out = str.slice(0, -2) + '.' + str.slice(-2);
  if (neg && num !== 0n) out = '-' + out;
  return out;
}

