This solves the discrete log via Pohlig–Hellman: it factors p−1 with a small-prime sieve plus Pollard rho (with Miller–Rabin), solves each prime-power sub-DLP with baby-step/giant-step, and combines residues via CRT, with brute-force fallbacks and a final verification. It assumes p−1 is reasonably smooth (factors up to ~10^12), which is the only way a 200-bit DLP is feasible in 300 ms.

The bug was in the Pohlig–Hellman digit accumulation (a garbled expression instead of d·q^k). Fixed version:

```js
function solve(input) {
  const p = BigInt(input.p), g = BigInt(input.g), h = BigInt(input.h) % p;
  const n = p - 1n;

  const powmod = (b, e, m) => { b %= m; if (b < 0n) b += m; let r = 1n; while (e > 0n) { if (e & 1n) r = r * b % m; b = b * b % m; e >>= 1n; } return r; };
  const gcd = (a, b) => { while (b) { const t = a % b; a = b; b = t; } return a < 0n ? -a : a; };
  const egcd = (a, b) => { let x0 = 1n, x1 = 0n; while (b) { const q = a / b; let t = a % b; a = b; b = t; t = x0 - q * x1; x0 = x1; x1 = t; } return [a, x0]; };
  const invmod = (a, m) => { const [gg, x] = egcd(((a % m) + m) % m, m); if (gg !== 1n) return null; return ((x % m) + m) % m; };
  const isqrt = (nn) => { if (nn < 2n) return nn; let x = nn, y = (x + 1n) / 2n; while (y < x) { x = y; y = (x + nn / x) / 2n; } return x; };

  function isPrime(nn) {
    if (nn < 2n) return false;
    for (const sp of [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n]) if (nn % sp === 0n) return nn === sp;
    let d = nn - 1n, r = 0n;
    while ((d & 1n) === 0n) { d >>= 1n; r++; }
    for (const a of [2n, 3n, 5n, 7n, 11n, 13n, 17n, 19n, 23n, 29n, 31n, 37n]) {
      if (a % nn === 0n) continue;
      let x = powmod(a, d, nn);
      if (x === 1n || x === nn - 1n) continue;
      let ok = false;
      for (let i = 1n; i < r; i++) { x = x * x % nn; if (x === nn - 1n) { ok = true; break; } }
      if (!ok) return false;
    }
    return true;
  }

  function rho(nn) {
    if (nn % 2n === 0n) return 2n;
    let c = 1n;
    while (true) {
      let x = 2n, y = 2n;
      while (true) {
        let prod = 1n;
        for (let i = 0; i < 128; i++) {
          x = (x * x + c) % nn;
          y = (y * y + c) % nn; y = (y * y + c) % nn;
          prod = prod * ((x - y + nn) % nn) % nn;
        }
        if (x === y) break;
        const d = gcd(prod, nn);
        if (d !== 1n) { if (d !== nn) return d; break; }
      }
      c++;
    }
  }

  // factor n = p-1
  const factors = new Map();
  let rem = n;
  {
    const L = 100000, sieve = new Uint8Array(L + 1), pr = [];
    for (let i = 2; i <= L; i++) if (!sieve[i]) { pr.push(BigInt(i)); for (let j = i * i; j <= L; j += i) sieve[j] = 1; }
    for (const q of pr) while (rem % q === 0n) { rem /= q; factors.set(q, (factors.get(q) || 0) + 1); }
  }
  if (rem > 1n) {
    const stack = [rem];
    while (stack.length) {
      const m = stack.pop();
      if (m === 1n) continue;
      if (isPrime(m)) { factors.set(m, (factors.get(m) || 0) + 1); continue; }
      const d = rho(m);
      stack.push(d); stack.push(m / d);
    }
  }

  // BSGS in subgroup of order q
  function bsgs(a, b, q) {
    const m = isqrt(q) + 1n;
    const table = new Map();
    let cur = 1n;
    for (let j = 0n; j < m; j++) { if (!table.has(cur)) table.set(cur, j); cur = cur * a % p; }
    const c = powmod(invmod(a, p), m, p);
    let y = b;
    for (let i = 0n; i <= m; i++) {
      const j = table.get(y);
      if (j !== undefined) return i * m + j;
      y = y * c % p;
    }
    return null;
  }

  // Pohlig-Hellman
  let X = 0n, M = 1n, complete = true;
  for (const [q, e] of factors) {
    let qe = 1n; for (let i = 0; i < e; i++) qe *= q;
    if (q > 1000000000000n) { complete = false; continue; }
    const cof = n / qe;
    const gq = powmod(g, cof, p);
    const hq = powmod(h, cof, p);
    let qe1 = 1n; for (let i = 1; i < e; i++) qe1 *= q; // q^(e-1)
    const alpha = powmod(gq, qe1, p); // order q
    let x = 0n;
    for (let k = 0; k < e; k++) {
      let qk = 1n; for (let i = 0; i < e - 1 - k; i++) qk *= q; // q^(e-1-k)
      const cur = powmod(gq, x, p);
      const t = powmod(hq * invmod(cur, p) % p, qk, p);
      const d = bsgs(alpha, t, q);
      if (d === null) { x = null; break; }
      x += d * (q ** BigInt(k));
    }
    if (x === null) { complete = false; continue; }
    // CRT combine (x mod qe) with (X mod M); M and qe coprime
    const inv = invmod(M % qe, qe);
    if (inv === null) { complete = false; continue; }
    const t = (((x - X) % qe) + qe) % qe * inv % qe;
    X += M * t;
    M *= qe;
  }

  X %= M;
  if (powmod(g, X, p) === h) return X.toString();
  if (complete) {
    // g may not generate the full group; X is correct mod ord(g)
    let cand = X;
    for (let t = 0n; t < 5000n; t++) {
      if (powmod(g, cand, p) === h) return cand.toString();
      cand += M;
    }
  } else {
    // partial: search over multiples of M
    const gM = powmod(g, M, p), base = powmod(g, X, p);
    const target = h * invmod(base, p) % p;
    let cur = 1n;
    const lim = p / M > 300000n ? 300000n : p / M;
    for (let t = 0n; t <= lim; t++) {
      if (cur === target) return (X + M * t).toString();
      cur = cur * gM % p;
    }
  }
  return (X % (p - 1n)).toString();
}
```

The core fix: each Pohlig–Hellman digit is now added as `d * q^k` (the previous expression was corrupted). It still factors p−1 with sieve + Pollard rho, does BSGS per prime, and CRT-combines; if some factor exceeds 10^12 it falls back to a linear search over the remaining cofactor.

